#include <math.h>
#include <stdio.h>

static void show_sqrt(double value)
{
    if (!isfinite(value) || value < 0.0) {
        printf("sqrt input %.3f is outside this program's accepted domain\n", value);
        return;
    }

    {
        double result = sqrt(value);
        if (isfinite(result)) {
            printf("sqrt(%.3f) = %.3f\n", value, result);
        } else {
            puts("sqrt produced a non-finite result.");
        }
    }
}

int main(void)
{
    double values[] = {25.0, 0.0, -4.0};
    size_t i;

    for (i = 0U; i < sizeof values / sizeof values[0]; ++i) {
        show_sqrt(values[i]);
    }

#if defined(INFINITY)
    show_sqrt(INFINITY);
#endif
#if defined(NAN)
    show_sqrt(NAN);
    if (isnan(NAN)) {
        puts("NaN was classified with isnan.");
    }
#endif
    return 0;
}

#include <math.h>
#include <stdio.h>

static int nearly_equal(double a, double b, double absolute_tolerance,
                        double relative_tolerance)
{
    double difference = fabs(a - b);
    double scale = fmax(fabs(a), fabs(b));

    return difference <= absolute_tolerance + relative_tolerance * scale;
}

int main(void)
{
    const double pi = acos(-1.0);
    const double degrees = 60.0;
    const double radians = degrees * (pi / 180.0);
    const double actual = sin(radians);
    const double expected = sqrt(3.0) / 2.0;

    printf("sin(%.1f degrees) = %.12f\n", degrees, actual);
    printf("Expected value   = %.12f\n", expected);
    printf("Within tolerance = %s\n",
           nearly_equal(actual, expected, 1e-12, 1e-12) ? "yes" : "no");
    return 0;
}
